<template><main class="detail-page"><el-button link @click="router.push('/admin/public-models')">← {{ t('publicModelsAdmin.back') }}</el-button><el-skeleton v-if="loading && !model" :rows="8" animated/><el-alert v-else-if="error" ref="errorAlert" role="alert" type="error" :closable="false" :title="errorTitle"><p v-if="error.requestId">{{ t('publicModelsAdmin.requestId') }}: <code>{{ error.requestId }}</code></p><el-button link @click="refresh">{{ t('publicModelsAdmin.refresh') }}</el-button></el-alert><template v-else-if="model"><header><div><p class="eyebrow">{{ model.provider }}</p><h1 tabindex="-1">{{ model.displayName }}</h1><code>{{ model.modelKey }}</code></div><div class="actions"><el-button @click="showEdit=true">{{ t('publicModelsAdmin.edit') }}</el-button><el-button v-if="model.status==='active'" @click="openDeactivate">{{ t('publicModelsAdmin.inactivate') }}</el-button><el-button v-else @click="activate">{{ t('publicModelsAdmin.activate') }}</el-button><el-dropdown @command="command"><el-button :aria-label="t('publicModelsAdmin.more')">•••</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="delete" class="danger">{{ t('publicModelsAdmin.delete') }}</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></header><el-descriptions border :column="2"><el-descriptions-item :label="t('publicModelsAdmin.upstreamModelId')"><code>{{ model.upstreamModelId }}</code></el-descriptions-item><el-descriptions-item :label="t('publicModelsAdmin.status')">{{ t(`publicModelsAdmin.statuses.${model.status}`) }}</el-descriptions-item><el-descriptions-item :label="t('publicModelsAdmin.contextWindow')">{{ model.contextWindow }}</el-descriptions-item><el-descriptions-item :label="t('publicModelsAdmin.publicDisplayGroup')">{{ model.publicDisplayGroup||t('publicModelsAdmin.notSet') }}</el-descriptions-item><el-descriptions-item :label="t('publicModelsAdmin.capabilities')">{{ model.capabilities.join(', ')||t('publicModelsAdmin.none') }}</el-descriptions-item><el-descriptions-item :label="t('publicModelsAdmin.endpointTypes')">{{ model.endpointTypes.join(', ')||t('publicModelsAdmin.none') }}</el-descriptions-item><el-descriptions-item :label="t('publicModelsAdmin.publicRestrictions')">{{ model.publicRestrictions.join(', ')||t('publicModelsAdmin.none') }}</el-descriptions-item><el-descriptions-item :label="t('publicModelsAdmin.inputPrice')">{{ price(model.inputPriceUsdPerMillionTokens) }}</el-descriptions-item><el-descriptions-item :label="t('publicModelsAdmin.outputPrice')">{{ price(model.outputPriceUsdPerMillionTokens) }}</el-descriptions-item><el-descriptions-item :label="t('publicModelsAdmin.priceSource')">{{ model.priceSource||t('publicModelsAdmin.notSet') }}</el-descriptions-item><el-descriptions-item :label="t('publicModelsAdmin.priceReviewer')">{{ model.priceReviewer||t('publicModelsAdmin.notSet') }}</el-descriptions-item><el-descriptions-item :label="t('publicModelsAdmin.priceEffectiveAt')">{{ time(model.priceEffectiveAt) }}</el-descriptions-item><el-descriptions-item :label="t('publicModelsAdmin.revision')">{{ model.revision }}</el-descriptions-item></el-descriptions></template>
  <el-alert v-if="conflictComparison" class="conflict" type="warning" :closable="false" :title="t('publicModelsAdmin.conflict')"><dl><template v-for="row in conflictRows" :key="row.key"><dt>{{ row.key }}</dt><dd>{{ row.before }} → {{ row.latest }}</dd></template></dl></el-alert>
  <p class="sr-only" aria-live="polite">{{ loading?t('publicModelsAdmin.loading'):'' }}</p><PublicModelForm v-model="showEdit" mode="edit" :model="model" :busy="loading" :error="formError" @submit="update" />
  <el-dialog v-model="showDeactivate" :title="t('publicModelsAdmin.inactivate')"><el-input v-model="deactivateReason" maxlength="128"/><template #footer><el-button @click="showDeactivate=false">{{t('publicModelsAdmin.cancel')}}</el-button><el-button type="warning" @click="deactivate">{{t('publicModelsAdmin.confirm')}}</el-button></template></el-dialog>
  <el-dialog v-model="showDelete" :title="t('publicModelsAdmin.delete')"><el-alert type="warning" :closable="false" :title="t('publicModelsAdmin.permanentWarning')"/><el-form label-position="top"><el-form-item :label="t('publicModelsAdmin.reason')"><el-input v-model="deleteForm.reason" maxlength="128"/></el-form-item><el-form-item :label="t('publicModelsAdmin.currentPassword')"><el-input v-model="deleteForm.currentPassword" type="password" autocomplete="current-password"/></el-form-item></el-form><template #footer><el-button @click="closeDelete">{{t('publicModelsAdmin.cancel')}}</el-button><el-button type="danger" :disabled="!deleteForm.reason||!deleteForm.currentPassword" @click="remove">{{t('publicModelsAdmin.confirmDelete')}}</el-button></template></el-dialog>
</main></template>
<script setup>
import { computed,onBeforeUnmount,onMounted,reactive,ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import { ElMessage } from 'element-plus';import { usePublicModelAdminStore } from '@/stores/publicModelAdmin';import { useI18n } from '@/composables/useI18n';import PublicModelForm from '@/components/public-admin/PublicModelForm.vue'
const route=useRoute(),router=useRouter(),store=usePublicModelAdminStore(),{t}=useI18n();const showEdit=ref(false),showDeactivate=ref(false),showDelete=ref(false),deactivateReason=ref(''),formError=ref(''),conflictComparison=ref(null);const deleteForm=reactive({reason:'',currentPassword:''});const model=computed(()=>store.detail),loading=computed(()=>store.loading),error=computed(()=>store.error);const errorTitle=computed(()=>error.value?.code==='revision_conflict'?t('publicModelsAdmin.conflict'):t('publicModelsAdmin.loadFailed'));const expectedRevision=computed(()=>model.value?.revision);const conflictRows=computed(()=>{const c=conflictComparison.value;if(!c)return[];return Object.keys(c.attempted).filter(key=>key!=='expectedRevision'&&String(c.before?.[key]??'')!==String(c.latest?.[key]??'')).map(key=>({key,before:String(c.before?.[key]??''),latest:String(c.latest?.[key]??'')}))})
async function refresh(){await store.loadDetail(String(route.params.guid))}async function conflictAware(work,attempted={}){const before=model.value?{...model.value}:null;const out=await work();if(store.error?.code==='revision_conflict'){showEdit.value=false;showDeactivate.value=false;showDelete.value=false;deleteForm.currentPassword='';ElMessage.warning(t('publicModelsAdmin.conflict'));await refresh();conflictComparison.value={before,attempted,latest:model.value?{...model.value}:null}}return out}async function update(form){formError.value='';const out=await conflictAware(()=>store.update(model.value.guid,form,model.value),form);if(out){showEdit.value=false;conflictComparison.value=null}else formError.value=store.error?.code??'request_failed'}async function activate(){await conflictAware(()=>store.activate(model.value.guid,expectedRevision.value),{status:'active'})}function openDeactivate(){deactivateReason.value='';showDeactivate.value=true}async function deactivate(){if(!deactivateReason.value)return;const out=await conflictAware(()=>store.deactivate(model.value.guid,expectedRevision.value,deactivateReason.value),{status:'inactive'});if(out)showDeactivate.value=false}function command(value){if(value==='delete')showDelete.value=true}function closeDelete(){deleteForm.currentPassword='';deleteForm.reason='';showDelete.value=false}async function remove(){const attempted={status:'deleted'};const out=await conflictAware(()=>store.remove({guid:model.value.guid,expectedRevision:expectedRevision.value,reason:deleteForm.reason,currentPassword:deleteForm.currentPassword}),attempted);deleteForm.currentPassword='';if(out)await router.replace('/admin/public-models')}const price=v=>v===null?t('publicModelsAdmin.notSet'):`$${v} USD / 1M tokens`;const time=v=>v===null?t('publicModelsAdmin.notSet'):new Date(v).toLocaleString();onMounted(refresh);onBeforeUnmount(()=>{deleteForm.currentPassword='';store.cancel()})
</script>
<style scoped>.detail-page{max-width:1100px;margin:auto;padding:24px;height:100%;overflow:auto}header{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin:24px 0}.actions{display:flex;gap:8px}.eyebrow{color:var(--text-secondary)}code{font-family:ui-monospace,monospace}.danger{color:var(--el-color-danger)}.conflict{margin:18px 0}.conflict dl{display:grid;grid-template-columns:max-content 1fr;gap:6px 12px}.conflict dd{margin:0}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}@media(max-width:700px){.detail-page{padding:16px}header{flex-direction:column}.actions{width:100%;flex-wrap:wrap}.detail-page :deep(.el-descriptions__body){overflow:auto}.conflict dl{grid-template-columns:1fr}}</style>
